def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math, statistics
    if horizon <= 0:
        return []
    x = []
    for v in history:
        try:
            z = float(v)
            if math.isfinite(z):
                x.append(z)
        except (TypeError, ValueError):
            pass
    if not x:
        return [0.0] * horizon
    p = 24
    if len(x) < 2 * p:
        return [statistics.median(x[-min(12, len(x)):])] * horizon

    def one(seq, method):
        vals = []
        j = len(seq) - p
        while j >= 0 and len(vals) < 6:
            vals.append(seq[j])
            j -= p
        if not vals:
            return seq[-1]
        if method == 0:
            return vals[0]
        if method == 1:
            return statistics.median(vals[:3])
        if method == 2:
            return sum(vals[:2]) / len(vals[:2])
        if method == 3:
            return 0.7 * vals[0] + 0.3 * statistics.median(vals[:4])
        return statistics.median(vals)

    def path(train, method, steps):
        seq = list(train)
        out = []
        for _ in range(steps):
            y = one(seq, method)
            seq.append(y)
            out.append(y)
        return out

    origins = list(range(2 * p, len(x) - p + 1, p))[-4:]
    methods = range(5)
    risks = []
    for method in methods:
        scores = []
        for origin in origins:
            pred = path(x[:origin], method, p)
            actual = x[origin:origin + p]
            terms = []
            for a, b in zip(actual, pred):
                den = abs(a) + abs(b)
                terms.append(0.0 if den < 1e-12 else 200.0 * abs(a - b) / den)
            scores.append(sum(terms) / len(terms))
        if scores:
            risk = statistics.median(scores) + 0.35 * max(scores)
        else:
            risk = float(method)
        risks.append((risk, method))
    chosen = sorted(risks)[:2]
    trajectories = [path(x, method, horizon) for _, method in chosen]
    weights = [1.0 / max(1e-6, risk) for risk, _ in chosen]
    lo, hi = min(x), max(x)
    result = []
    for k in range(horizon):
        y = sum(w * trajectory[k] for w, trajectory in zip(weights, trajectories)) / sum(weights)
        result.append(min(hi, max(lo, y)))
    return result

def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math, statistics
    if horizon <= 0:
        return []
    x = []
    for value in history:
        try:
            value = float(value)
            if math.isfinite(value):
                x.append(value)
        except (TypeError, ValueError):
            pass
    if not x:
        return [0.0] * horizon
    if len(x) < 80:
        return [statistics.median(x[-min(15, len(x)):])] * horizon

    y = x[:]
    for i in range(3, len(x) - 3):
        window = x[i - 3:i + 4]
        med = statistics.median(window)
        mad = statistics.median(abs(v - med) for v in window)
        if mad > 0 and abs(x[i] - med) > 7.0 * 1.4826 * mad:
            y[i] = med

    def make_path(data, steps, p):
        n = len(data)
        blocks = []
        start = max(0, n - 5 * p)
        for end in range(start + p, n + 1, p):
            block = data[end - p:end]
            if len(block) == p:
                blocks.append((end, statistics.median(block)))
        if len(blocks) < 2:
            level = statistics.median(data[-p:])
            return [data[n - p + (k % p)] + level - statistics.median(data[-p:]) for k in range(steps)]
        changes = [blocks[j][1] - blocks[j - 1][1] for j in range(1, len(blocks))]
        cycle_change = statistics.median(changes[-3:])
        if len(changes) >= 3:
            spread = statistics.median(abs(v - cycle_change) for v in changes[-3:])
            cycle_change *= 1.0 / (1.0 + spread / 3.0)
        target_level = statistics.median(data[-p:])
        phase_values = {}
        for i in range(max(0, n - 4 * p), n):
            block_end = n - ((n - 1 - i) // p) * p
            block_start = max(0, block_end - p)
            block_level = statistics.median(data[block_start:block_end])
            phase_values.setdefault(i % p, []).append(data[i] - block_level)
        template = {phase: statistics.median(values) for phase, values in phase_values.items()}
        fitted_last = target_level + template.get((n - 1) % p, 0.0)
        continuity = data[-1] - fitted_last
        out = []
        for k in range(steps):
            cycles_ahead = (k + 1) / float(p)
            level = target_level + cycle_change * cycles_ahead
            seasonal = template.get((n + k) % p, 0.0)
            anchor = continuity * math.exp(-(k + 1) / max(1.0, 0.3 * p))
            out.append(level + seasonal + anchor)
        return out

    candidates = []
    for p in range(38, min(48, len(y) // 3) + 1):
        errors = []
        for back in (3, 2, 1):
            cut = len(y) - back * p
            if cut < 3 * p:
                continue
            actual = y[cut:cut + p]
            predicted = make_path(y[:cut], len(actual), p)
            for a, b in zip(actual, predicted):
                errors.append(200.0 * abs(a - b) / max(1e-9, abs(a) + abs(b)))
        if errors:
            candidates.append((statistics.median(errors), p))
    if not candidates:
        return [statistics.median(y[-20:])] * horizon
    selected = sorted(candidates)[:3]
    paths = [make_path(y, horizon, p) for _, p in selected]
    weights = [1.0 / max(0.25, score) for score, _ in selected]
    total = sum(weights)
    return [sum(w * path[k] for w, path in zip(weights, paths)) / total for k in range(horizon)]
